import pandas as pd

def code_of(dtype_str):
    if dtype_str == "object":
        return 0.0
    if dtype_str == "Int64":
        return 1.0
    if dtype_str == "UInt64":
        return 2.0
    return 9.0

def record(name, fn):
    try:
        result = fn()
        probe(name, code_of(str(result.dtype)))
    except Exception:
        probe(name, -1.0)

record("ser_2p64", lambda: pd.Series([2**64], dtype=object).convert_dtypes())
record("ser_neg2p63m1", lambda: pd.Series([-(2**63) - 1], dtype=object).convert_dtypes())
record("ser_10p400", lambda: pd.Series([10**400], dtype=object).convert_dtypes())
record("ser_2p63_neg1", lambda: pd.Series([2**63, -1], dtype=object).convert_dtypes())
record("ser_2p64_NA", lambda: pd.Series([2**64, pd.NA], dtype=object).convert_dtypes())
record("ser_2p63_NA", lambda: pd.Series([2**63, pd.NA], dtype=object).convert_dtypes())
record("ser_2p62_NA", lambda: pd.Series([2**62, pd.NA], dtype=object).convert_dtypes())

def frame_col(col):
    def f():
        return pd.DataFrame({"a": [2**64, 1], "b": [1, 2]}, dtype=object).convert_dtypes()[col]
    return f

record("df_col_a", frame_col("a"))
record("df_col_b", frame_col("b"))

record("ser_pyarrow_2p64", lambda: pd.Series([2**64], dtype=object).convert_dtypes(dtype_backend="pyarrow"))

