import pandas as pd

def dtype_code(obj):
    try:
        dt = str(obj.dtype)
    except Exception:
        return -3.0
    if dt == "object":
        return 0.0
    if dt == "Int64":
        return 1.0
    if dt == "UInt64":
        return 2.0
    if "int64" in dt:
        return 3.0
    if "uint64" in dt:
        return 4.0
    return 5.0

def safe(fn):
    try:
        return dtype_code(fn())
    except OverflowError:
        return -1.0
    except Exception:
        return -2.0

probe("series_2^64", safe(lambda: pd.Series([2**64], dtype=object).convert_dtypes()))
probe("series_neg_2^63_minus_1", safe(lambda: pd.Series([-(2**63) - 1], dtype=object).convert_dtypes()))
probe("series_10^400", safe(lambda: pd.Series([10**400], dtype=object).convert_dtypes()))
probe("series_2^63_and_neg1", safe(lambda: pd.Series([2**63, -1], dtype=object).convert_dtypes()))
probe("series_2^64_and_NA", safe(lambda: pd.Series([2**64, pd.NA], dtype=object).convert_dtypes()))
probe("series_2^63_and_NA", safe(lambda: pd.Series([2**63, pd.NA], dtype=object).convert_dtypes()))

try:
    _df = pd.DataFrame({"a": [2**64, 1], "b": [1, 2]}, dtype=object).convert_dtypes()
    probe("frame_col_a", dtype_code(_df["a"]))
    probe("frame_col_b", dtype_code(_df["b"]))
except Exception:
    probe("frame_col_a", -1.0)
    probe("frame_col_b", -1.0)

probe("series_2^64_pyarrow", safe(lambda: pd.Series([2**64], dtype=object).convert_dtypes(dtype_backend="pyarrow")))
